import { zodResolver } from '@hookform/resolvers/zod';
import clsx from 'clsx';
import { useEffect, useMemo, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useAuthTimer } from '~/entities/mobile-verification/lib/use-auth-timer';
import { useOnSubmit } from '~/entities/mobile-verification/lib/use-on-submit';
import { FormPhase, Inputs, RealSelfAuthFormSchema, TELECOM_CARRIER } from '~/entities/mobile-verification/model/types';
import { AuthNumberInput } from '~/entities/mobile-verification/ui/auth-number-input';
import { CallbackResult, VerificationType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { Select } from '~/shared/ui/selects/select';
import { TextInput } from '~/shared/ui/text-input/text-input';

export const MobileVerificationPage = () => {
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const [formPhase, setFormPhase] = useState(FormPhase.HAS_NOT_REQUESTED_AUTH_NUMBER);
  const [serverAuthNumber, setServerAuthNumber] = useState('');
  const form = useForm<Inputs>({ mode: 'all', resolver: zodResolver(RealSelfAuthFormSchema) });
  const {
    handleSubmit,
    register,
    setError,
    clearErrors,
    setValue,
    setFocus,
    getValues,
    watch,
    formState: { isValid },
  } = form;

  const { remainingTime, handleRetryAuthNumber, startTimer, remainingTimeText } = useAuthTimer({
    setError,
    setFormPhase,
    setValue,
    clearErrors,
  });

  const { authNumber } = watch();
  const telecomTypeCd = getValues('telecomTypeCd');

  const isAllValid = useMemo(
    () => isValid && remainingTime > 0 && (telecomTypeCd?.length ?? 0) > 0,
    [isValid, remainingTime, telecomTypeCd],
  );

  const { onSubmit } = useOnSubmit({
    formPhase,
    serverAuthNumber,
    setFormPhase,
    startTimer,
    setFocus,
    setValue,
    setServerAuthNumber,
    setError,
  });

  useEffect(() => {
    setTimeout(() => {
      form.setFocus('koreanNm');
    }, 300);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.setFocus]);

  return (
    <>
      <div className="sub-desc">
        <p
          dangerouslySetInnerHTML={{
            __html: i18n.t(
              state?.verificationType === VerificationType.신규유저
                ? 'text:verificationForNewUser'
                : 'text:verificationForExistingUser',
            ),
          }}
        />
      </div>
      <FormProvider {...form}>
        <form onSubmit={handleSubmit(onSubmit)} className="ipt-form-area">
          <TextInput
            label={i18n.t('name')}
            disabled={formPhase === FormPhase.REQUESTED_AUTH_NUMBER}
            {...register('koreanNm')}
          />
          <TextInput
            label={i18n.t('idNumber7Digits')}
            inputMode="numeric"
            minLength={7}
            maxLength={7}
            disabled={formPhase === FormPhase.REQUESTED_AUTH_NUMBER}
            {...register('rlnmNo')}
          />

          <div className="flex flex-row gap-[7px]">
            <Select
              classStr="shrink-0 basis-24"
              placeholder={i18n.t('selectCarrier')}
              labels={Object.keys(TELECOM_CARRIER)}
              values={Object.values(TELECOM_CARRIER)}
              name="telecomTypeCd"
              option={{ required: '' }}
              disabled={formPhase === FormPhase.REQUESTED_AUTH_NUMBER}
            />
            <TextInput
              classStr="grow"
              label={i18n.t('phoneNumberWithoutHyphens')}
              inputMode="numeric"
              minLength={10}
              maxLength={11}
              disabled={formPhase === FormPhase.REQUESTED_AUTH_NUMBER}
              {...register('mbtlnum')}
            />
          </div>
          <AuthNumberInput
            formPhase={formPhase}
            remainingTimeText={remainingTimeText}
            remainingTime={remainingTime}
            register={register}
            handleRetryAuthNumber={handleRetryAuthNumber}
            serverAuthNumber={serverAuthNumber}
          />
          <div className="btn-area">
            {formPhase === FormPhase.HAS_NOT_REQUESTED_AUTH_NUMBER && (
              <button
                type="submit"
                disabled={!(isValid && String(telecomTypeCd ?? '').length > 0)}
                className={clsx('btm-btn app', { disabled: !(isValid && String(telecomTypeCd ?? '').length > 0) })}
              >
                {i18n.t('verificationRequest')}
              </button>
            )}
            {formPhase === FormPhase.REQUESTED_AUTH_NUMBER && (
              <button
                type="submit"
                disabled={
                  !isAllValid || String(authNumber ?? '').length !== 6 || serverAuthNumber === CallbackResult.에러
                }
                className={clsx('btm-btn app', {
                  disabled:
                    !isAllValid || String(authNumber ?? '').length !== 6 || serverAuthNumber === CallbackResult.에러,
                })}
              >
                {i18n.t('confirm')}
              </button>
            )}
          </div>
        </form>
      </FormProvider>
    </>
  );
};
