export const SelfAuthFormSchema = z.object({
  koreanNm: z
    .string()
    .min(1, i18n.t('validation:enterNamePrompt'))
    .min(2, i18n.t('validation:enterAtLeastTwoCharacters'))
    .regex(/^[가-힣\s]+$/, i18n.t('validation:enterKorean'))
    .max(20, i18n.t('validation:enterUpTo20Characters'))
    .refine((value: string) => !value.includes(' '), { message: '공백을 포함할 수 없습니다' }), // 한글명
  rlnmNo: z
    .string()
    .min(1, i18n.t('validation:enterBirthdate'))
    .min(8, i18n.t('validation:enterBirthdateIn8Digits'))
    .regex(/^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])$/, i18n.t('validation:enterBirthdateInCorrectFormat'))
    .refine(
      (value: string) => {
        if (!value) return false;
        const birthDate = new Date(Number(value.slice(0, 4)), Number(value.slice(4, 6)) - 1, Number(value.slice(6, 8)));
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const minDate = new Date(1900, 0, 1); // January 1, 1900
        return birthDate >= minDate;
      },
      { message: i18n.t('validation:enterDateAfter1900') },
    )
    .refine(
      (value: string) => {
        if (!value) return false;
        const birthDate = new Date(Number(value.slice(0, 4)), Number(value.slice(4, 6)) - 1, Number(value.slice(6, 8)));
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        return birthDate < today;
      },
      { message: i18n.t('validation:enterDateBeforeToday') },
    ), // 생년월일
  telecomTypeCd: z.string().trim(), // 통신사
  mbtlnum: z
    .string()
    .min(1, i18n.t('validation:enterPhoneNumber'))
    .regex(/^01[016789][0-9]{7,8}$/, i18n.t('validation:invalidPhoneNumberFormat')), // 이동전화번호
  pin: z.string().nullable().optional(), // PIN번호
  lbdyCrtfcTkn: z.string().nullable().optional(), // 생체인증Token
  lbdyCrtfcYn: z.string().nullable().optional(), // 생체인증사용여부
  appEsntlNo: z.string().nullable().optional(), // APP고유번호
  pushToken: z.string().nullable().optional(), // FCM토큰
  etcNtcnYn: z.string().nullable().optional(), // 기타알림여부
  stplatYn: z.string().nullable().optional(), // 약관동의여부
  authNumber: z.string().nullable().optional(),
});

