import React from 'react';
import { FormPhase } from '~/entities/mobile-verification/model/types';
import { CallbackResult } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { TextInput } from '~/shared/ui/text-input/text-input';

type AuthNumberInputProps = {
  formPhase: FormPhase;
  remainingTimeText: string;
  remainingTime: number;
  register: (...args: any[]) => any;
  handleRetryAuthNumber: () => void;
  serverAuthNumber: string;
};

export const AuthNumberInput = ({
  formPhase,
  remainingTimeText,
  remainingTime,
  register,
  handleRetryAuthNumber,
  serverAuthNumber,
}: AuthNumberInputProps) => {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    handleRetryAuthNumber();
  };
  return formPhase === FormPhase.REQUESTED_AUTH_NUMBER ? (
    <div className="mb-[15px]">
      <TextInput
        label={
          <>
            {i18n.t('validation:enter6DigitVerificationCode')} <span className="pin-timer">({remainingTimeText})</span>
          </>
        }
        inputMode="numeric"
        minLength={6}
        maxLength={6}
        disabled={remainingTime <= 0 || serverAuthNumber === CallbackResult.에러}
        {...register('authNumber')}
      />
      <p className="pin-info">
        {serverAuthNumber === CallbackResult.에러
          ? i18n.t('validation:reTryText')
          : i18n.t('validation:didNotReceiveVerificationText')}
        <button className="pin-retry" onClick={handleClick}>
          {i18n.t('resend')}
        </button>
      </p>
    </div>
  ) : (
    <></>
  );
};
